package chat.simplex.common.model

const val QRYPTANA_INVITATION_TITLE = "Qryptana - Invitation"
const val QRYPTANA_INVITATION_PREVIEW_IMAGE = "data:image/png;base64,"

private const val QRYPTANA_DOMAIN = "qryptana.foundation"

fun isQryptanaDomain(url: String): Boolean {
  val host = runCatching { java.net.URI(url).host }.getOrNull()?.lowercase() ?: return false
  return host == QRYPTANA_DOMAIN || host.endsWith(".$QRYPTANA_DOMAIN")
}

fun isQryptanaInvitationLink(url: String): Boolean {
  if (!isQryptanaDomain(url)) return false
  val lower = url.lowercase()
  return lower.contains("/contact") || lower.contains("/invitation") ||
    lower.contains("/a#") || lower.contains("/g#")
}
